/**
 * SCHEMA and registry of the page help content.
 *
 * This file contains NO LITERAL TEXT — only i18n keys. All texts live as TR+EN pairs
 * in `src/app/i18n/help.i18n.ts` (the datatype-help pattern from
 * CoreLogicUI). This way language switching works from one place and a missing translation
 * fails the i18n test instead of showing up on screen as a raw key.
 *
 * Keys are generated by convention: for a topic `x`
 *   pc.help.x.title / .summary
 *   pc.help.x.field.<name>.label / .desc
 *   pc.help.x.rule.<name>.label / .desc
 *   pc.help.x.notes
 */

/** What a column/field means and how it is obtained. */
export interface HelpEntry {
  labelKey: string;
  descKey: string;
}

export interface PageHelpTopic {
  titleKey: string;
  summaryKey: string;
  /** The page's column/field glossary — "what does this mean, where does it come from". */
  fields: HelpEntry[];
  /** Lifecycle / business rules — only on pages that actually have rules. */
  rules?: HelpEntry[];
  /** Status chain strip, e.g. ['Draft','Published','Expired']. */
  lifecycle?: string[];
  /** The yellow "Dikkat" (Caution) box. */
  notesKey?: string;
}

export type PageHelpId = string;

// ── Key-generating helpers (avoid repetition) ─────────────────────────────────
const field = (topic: string, name: string): HelpEntry => ({
  labelKey: `pc.help.${topic}.field.${name}.label`,
  descKey: `pc.help.${topic}.field.${name}.desc`
});
const rule = (topic: string, name: string): HelpEntry => ({
  labelKey: `pc.help.${topic}.rule.${name}.label`,
  descKey: `pc.help.${topic}.rule.${name}.desc`
});

/** Factory that shortens topic definitions — title/summary/notes keys come from the convention. */
function topic(
  id: string,
  fieldNames: string[],
  options: { rules?: string[]; lifecycle?: string[]; notes?: boolean } = {}
): PageHelpTopic {
  return {
    titleKey: `pc.help.${id}.title`,
    summaryKey: `pc.help.${id}.summary`,
    fields: fieldNames.map(n => field(id, n)),
    rules: options.rules?.map(n => rule(id, n)),
    lifecycle: options.lifecycle,
    notesKey: options.notes ? `pc.help.${id}.notes` : undefined
  };
}

